 for(const data of [{name:'  ',directoryId},{name:'有效名称',directoryId:'invalid'},null]){const r=await page.request.post(base+'/api/item',{data});assert.equal(r.status(),400);}
 assert.equal((await (await page.request.get(base+'/api/item')).json()).item.name,'秋日产品 A');
 await page.locator('#back').click();await page.waitForURL(base+'/settings');assert.equal(await page.locator('#service').textContent(),'现有服务');
 fs.writeFileSync('evidence/results.json',JSON.stringify({checks:['动态目录来自服务端','填写选择保存草稿','同一服务刷新读回','503保留表单且存储未变','空白名称、无效目录、null返回400且原值未变','返回浏览器历史/settings保持可用','图片单组内三行右侧操作'],network,inspect},null,2));
 console.log('全部检查通过');
 } finally {await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1});

